function submitEmailAuth(mode){if(!supabaseClient||!supabaseClient.auth)return showToast("Account service unavailable");var email=($("#authEmail")&&$("#authEmail").value||"").trim().toLowerCase(),password=$("#authPassword")&&$("#authPassword").value||"",name=($("#authName")&&$("#authName").value||"").trim().slice(0,32);if(!email||password.length<6)return showToast("Enter email and 6+ character password");showToast(mode==="signup"?"Creating account...":"Signing in...");var task=mode==="signup"?supabaseClient.auth.signUp({email:email,password:password,options:{data:{display_name:name}}}):supabaseClient.auth.signInWithPassword({email:email,password:password});return task.then(function(res){if(res.error)throw res.error;if(!res.data.session)return showToast("Check your email to finish sign in");authAccessToken=res.data.session.access_token;appState.auth.accessToken=authAccessToken;authState={id:res.data.user.id,email:res.data.user.email||email,isAnonymous:false,updated_at:new Date().toISOString()};cacheState.setAuthState(authState);if(name&&!accountPrefs.display_name)accountPrefs.display_name=name;return accountRequest("claim",{favorites:favs,preferences:accountPrefs})}).then(function(){trackAppHeartbeat("app_open");maybeCapturePresence("foreground");startLiveLocationWatch();loadRewardSummary();loadDeviceProfile();renderAll();showToast(mode==="signup"?"Welcome to LineUp":"Signed in")}).catch(function(err){showToast(err&&err.message?err.message:"Account sign in failed")})}
