function hasGeo(){return !!navigator.geolocation}
function getCurrentGeo(){return new Promise(function(resolve,reject){if(!hasGeo())return reject(new Error("location unavailable"));navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:9000,maximumAge:60000})})}
