function savePresenceState(state){presenceState=state;cacheState.setPresenceState(state)}
function presenceCopy(){if(locationBusy)return{title:"Checking location",detail:"Waiting for your phone"};if(!hasGeo())return{title:"Location unavailable",detail:"Use the native app build"};if(!presenceState)return{title:"Off",detail:"Tap to enable while using"};if(presenceState.nearest_venue_name)return{title:"On while using",detail:presenceState.nearest_venue_name+" · "+Math.round(presenceState.nearest_distance_m||0)+"m"};return{title:"On while using",detail:"Ready for verified signals"}}
function capturePresence(source,venueId,silent){if(locationBusy)return Promise.resolve(null);locationBusy=true;appState.ui.locationBusy=true;if(!silent)showToast("Checking location...");if(active==="profilePage")renderProfile();return getFreshPosition(0).then(function(pos){return sendLocationIngest("presence",venueId||null,pos,{source:source||"foreground"})}).then(function(data){savePresenceState({enabled:true,nearest_venue_id:data.nearest_venue_id,nearest_venue_name:data.nearest_venue_name,nearest_distance_m:data.nearest_distance_m,area:data.area,updated_at:new Date().toISOString()});accountPrefs.location_pref="enabled";cacheState.setAccountPrefs(accountPrefs);lastPresenceAt=Date.now();appState.location.lastPresenceAt=lastPresenceAt;if(!silent)showToast(data.nearest_venue_name?"Near "+data.nearest_venue_name:"Location enabled");return data}).catch(function(){if(!silent)showToast("Location not enabled");return null}).finally(function(){locationBusy=false;appState.ui.locationBusy=false;if(active==="profilePage")renderProfile()})}
function liveLocationAllowed(){return !!(authState&&hasGeo()&&(accountPrefs.location_pref==="enabled"||presenceState))}
function handleLivePosition(pos,source){if(!liveLocationAllowed()||document.visibilityState==="hidden"||liveLocationSending)return;if(Date.now()-liveLocationLastSent<35000)return;liveLocationSending=true;appState.ui.liveLocationSending=true;liveLocationLastSent=Date.now();appState.location.liveLocationLastSent=liveLocationLastSent;lastPosition={raw:pos,t:Date.now()};appState.location.lastPosition=lastPosition;sendLocationIngest("presence",null,pos,{source:source||"live_watch"}).then(function(data){savePresenceState({enabled:true,nearest_venue_id:data.nearest_venue_id,nearest_venue_name:data.nearest_venue_name,nearest_distance_m:data.nearest_distance_m,area:data.area,updated_at:new Date().toISOString()});accountPrefs.location_pref="enabled";cacheState.setAccountPrefs(accountPrefs);lastPresenceAt=Date.now();appState.location.lastPresenceAt=lastPresenceAt;if(active==="profilePage")renderProfile()}).catch(function(){}).finally(function(){liveLocationSending=false;appState.ui.liveLocationSending=false})}
function startLiveLocationWatch(force){if(liveLocationWatchId!=null||!authState||!hasGeo()||document.visibilityState==="hidden")return;if(!force&&!liveLocationAllowed()){if(navigator.permissions&&navigator.permissions.query){navigator.permissions.query({name:"geolocation"}).then(function(p){if(p.state==="granted")startLiveLocationWatch(true)}).catch(function(){startLiveLocationWatch(true)})}else startLiveLocationWatch(true);return}if(force&&accountPrefs.location_pref!=="enabled"){accountPrefs.location_pref="enabled";cacheState.setAccountPrefs(accountPrefs)}liveLocationWatchId=navigator.geolocation.watchPosition(function(pos){handleLivePosition(pos,"live_watch")},function(){stopLiveLocationWatch()},{enableHighAccuracy:true,timeout:12000,maximumAge:15000});appState.location.liveLocationWatchId=liveLocationWatchId}
function stopLiveLocationWatch(){if(liveLocationWatchId==null||!hasGeo())return;navigator.geolocation.clearWatch(liveLocationWatchId);liveLocationWatchId=null;liveLocationSending=false;appState.location.liveLocationWatchId=null;appState.ui.liveLocationSending=false}
function checkInCurrent(){if(!current)return;if(locationBusy)return;var venueName=current.name;locationBusy=true;appState.ui.locationBusy=true;showToast("Verifying check-in...");getFreshPosition(0).then(function(pos){return sendLocationIngest("check_in",current.id,pos,{source:"check_in"})}).then(function(data){if(data.verified){awardReward("checkin",venueName,{checkin_id:data.checkin&&data.checkin.id});recordActivity("Verified check-in",venueName+" · +15 pts");showToast("Verified at "+venueName);loadSupabaseStatus();loadDeviceProfile();if(authState)accountRequest("claim",{favorites:favs}).catch(function(){})}else showToast("Too far away to verify")}).catch(function(){showToast("Location check failed")}).finally(function(){locationBusy=false;appState.ui.locationBusy=false;if(current)renderDetail()})}
function maybeCapturePresence(source){if(!authState||!hasGeo()||locationBusy)return Promise.resolve(null);if(document.visibilityState&&document.visibilityState!=="visible")return Promise.resolve(null);if(Date.now()-lastPresenceAt<3*60000)return Promise.resolve(null);if(accountPrefs.location_pref==="enabled"||presenceState)return capturePresence(source||"foreground",null,true);if(navigator.permissions&&navigator.permissions.query){return navigator.permissions.query({name:"geolocation"}).then(function(p){return p.state==="granted"?capturePresence(source||"foreground",null,true):null}).catch(function(){return capturePresence(source||"foreground",null,true)})}return capturePresence(source||"foreground",null,true)}
