function localConfidenceScore(b){var base=b.conf==="high"?74:b.conf==="medium"?54:30,src=(b.sources||[]).join(" ").toLowerCase(),boost=0;if(src.indexOf("owner")>-1)boost+=18;if(src.indexOf("venue")>-1||src.indexOf("staff")>-1)boost+=16;if(src.indexOf("verified")>-1||src.indexOf("check")>-1)boost+=12;if(src.indexOf("scout")>-1)boost+=10;if(src.indexOf("report")>-1)boost+=8;if(src.indexOf("app")>-1||src.indexOf("directions")>-1)boost+=5;if(src.indexOf("historical")>-1||src.indexOf("typical")>-1)boost+=3;var fresh=b.fresh==null?90:b.fresh,decay=fresh<10?8:fresh<30?3:fresh>120?-18:fresh>60?-10:0,inputs=Math.min(10,(b.confSignals||0)*2);return base+boost+decay+inputs}
