function closeText(b){var now=new Date(new Date().toLocaleString("en-US",{timeZone:"America/Phoenix"})),m=now.getHours()*60+now.getMinutes(),o=b.open*60,c=b.close*60,overnight=c<=o,open=overnight?(m>=o||m<c):(m>=o&&m<c);if(!open)return "Closed · Opens "+hour(b.open);var diff=(overnight&&m>=o?c+1440-m:c-m);if(diff<=45)return "Closing soon · "+diff+"m";if(diff<=120)return "Closes in "+Math.floor(diff/60)+"h "+(diff%60)+"m";return "Closes at "+hour(b.close)}
